#!/usr/bin/env python3
# write-notifications-view.py — creates the missing notifications page view.
# Run from repo root.
import base64, os
os.makedirs("resources/views/tenant", exist_ok=True)
open("resources/views/tenant/notifications.blade.php","wb").write(base64.b64decode(''))
print("created resources/views/tenant/notifications.blade.php")
